import React, { useState } from 'react';


import Navbar from './components/Navbar';
import Toast from './components/Toast';
import Login from './components/Login';
import Register from './components/Register';
import BookList from './components/BookList';
import RequestQueue from './components/RequestQueue';
import styles from './App.module.css';

function App() {
  const [user, setUser] = useState(null);
  const [showRegister, setShowRegister] = useState(false);
  const [page, setPage] = useState('books');
  const [toast, setToast] = useState('');

  const showToast = (msg) => {
    setToast(msg);
  };

  const handleLogout = () => {
    setUser(null);
    setPage('books');
    localStorage.removeItem('token');
    showToast('Logged out');
  };

  const handleNav = (navPage) => {
    setPage(navPage);
  };

  return (
    <div className={styles.main}>
      <Toast message={toast} onClose={() => setToast('')} />
      <div className={styles.header}>Library Management System</div>
      {user && <Navbar user={user} onLogout={handleLogout} onNav={handleNav} />}
      {!user ? (
        showRegister ? (
          <>
            <Register onRegister={() => setShowRegister(false)} />
            <div style={{ color: '#fff', marginTop: 16 }}>
              Already have an account?{' '}
              <button style={{ background: 'none', color: '#667eea', border: 'none', cursor: 'pointer', textDecoration: 'underline' }} onClick={() => setShowRegister(false)}>Login</button>
            </div>
          </>
        ) : (
          <>
            <Login setUser={setUser} />
            <div style={{ color: '#fff', marginTop: 16 }}>
              Don't have an account?{' '}
              <button style={{ background: 'none', color: '#667eea', border: 'none', cursor: 'pointer', textDecoration: 'underline' }} onClick={() => setShowRegister(true)}>Register</button>
            </div>
          </>
        )
      ) : (
        <>
          <div className={styles.welcome}>Welcome, {user.name} ({user.role})</div>
          {page === 'books' && <BookList user={user} showToast={showToast} />}
          {user.role === 'librarian' && page === 'requests' && <RequestQueue user={user} showToast={showToast} />}
        </>
      )}
    </div>
  );
}

export default App;
